export type EnumPlayerScope = "PlayerScope.YOU" | "PlayerScope.OPPONENT" | "PlayerScope.EACH_PLAYER" | "PlayerScope.EACH_OPPONENT" | "PlayerScope.TARGET_PLAYER" | "PlayerScope.TARGET_OPPONENT" | "PlayerScope.ACTIVE_PLAYER" | "PlayerScope.CONTROLLER_OF" | "PlayerScope.OWNER_OF" | "PlayerScope.SPECIFIC" | "PlayerScope.MONARCH" | "PlayerScope.DEFENDING_PLAYER" | "PlayerScope.THAT_PLAYER" | "PlayerScope.TRIGGER_SOURCE_CONTROLLER" | "PlayerScope.REFERRED_PLAYER" | "PlayerScope.TRIGGER_PLAYER" | "PlayerScope.REMEMBERED_CONTROLLER" | "PlayerScope.REMEMBERED_OWNER" | "PlayerScope.TRIGGER_OBJECT_CONTROLLER" | "PlayerScope.TRIGGER_OBJECT_OWNER" | "PlayerScope.AFFECTED_CONTROLLER" | "PlayerScope.CHOSEN_PLAYER" | "PlayerScope.ENCHANTED_PLAYER";
export const PlayerScopeValues: Record<string, number> = { YOU: 0, OPPONENT: 1, EACH_PLAYER: 2, EACH_OPPONENT: 3, TARGET_PLAYER: 4, TARGET_OPPONENT: 5, ACTIVE_PLAYER: 6, CONTROLLER_OF: 7, OWNER_OF: 8, SPECIFIC: 9, MONARCH: 10, DEFENDING_PLAYER: 11, THAT_PLAYER: 12, TRIGGER_SOURCE_CONTROLLER: 4001, REFERRED_PLAYER: 13001, TRIGGER_PLAYER: 13002, REMEMBERED_CONTROLLER: 13003, REMEMBERED_OWNER: 13004, TRIGGER_OBJECT_CONTROLLER: 13005, TRIGGER_OBJECT_OWNER: 13006, AFFECTED_CONTROLLER: 13007, CHOSEN_PLAYER: 13008, ENCHANTED_PLAYER: 14001 };

export type EnumStep = "Step.UNTAP" | "Step.UPKEEP" | "Step.DRAW" | "Step.MAIN" | "Step.BEGINNING_OF_COMBAT" | "Step.DECLARE_ATTACKERS" | "Step.DECLARE_BLOCKERS" | "Step.FIRST_STRIKE_COMBAT_DAMAGE" | "Step.COMBAT_DAMAGE" | "Step.END_OF_COMBAT" | "Step.END_STEP" | "Step.CLEANUP";
export const StepValues: Record<string, number> = { UNTAP: 0, UPKEEP: 1, DRAW: 2, MAIN: 3, BEGINNING_OF_COMBAT: 4, DECLARE_ATTACKERS: 5, DECLARE_BLOCKERS: 6, FIRST_STRIKE_COMBAT_DAMAGE: 7, COMBAT_DAMAGE: 8, END_OF_COMBAT: 9, END_STEP: 10, CLEANUP: 11 };

/** Flag enum: "Supertype." then members joined by "|" (e.g. "Supertype.BASIC|LEGENDARY"), or "Supertype.NONE". Members: BASIC, LEGENDARY, ONGOING, SNOW, WORLD, TOKEN, HOST, ELITE. */
export type EnumSupertype = `Supertype.${string}`;
export const SupertypeBits: Record<string, number> = { NONE: 0, BASIC: 1, LEGENDARY: 2, ONGOING: 4, SNOW: 8, WORLD: 16, TOKEN: 32, HOST: 64, ELITE: 128 };

export type EnumTiming = "Timing.SORCERY" | "Timing.INSTANT";
export const TimingValues: Record<string, number> = { SORCERY: 0, INSTANT: 1 };

export type EnumValueKind = "ValueKind.CONSTANT" | "ValueKind.X" | "ValueKind.COUNT" | "ValueKind.POWER" | "ValueKind.TOUGHNESS" | "ValueKind.MANA_VALUE" | "ValueKind.LIFE_TOTAL" | "ValueKind.CARDS_IN_HAND" | "ValueKind.POISON_COUNTERS" | "ValueKind.ENERGY" | "ValueKind.COUNTERS" | "ValueKind.SUM" | "ValueKind.PRODUCT" | "ValueKind.DIFFERENCE" | "ValueKind.HALF_ROUNDED_UP" | "ValueKind.HALF_ROUNDED_DOWN" | "ValueKind.MAXIMUM" | "ValueKind.MINIMUM" | "ValueKind.GREATEST_AMONG" | "ValueKind.LEAST_AMONG" | "ValueKind.UNCHANGED" | "ValueKind.DEVOTION" | "ValueKind.COLOURS_AMONG" | "ValueKind.MANA_SPENT" | "ValueKind.COST_PAID_POWER" | "ValueKind.COST_PAID" | "ValueKind.EVENT_AMOUNT" | "ValueKind.EVENT_COUNT_THIS_TURN" | "ValueKind.PARTY_SIZE" | "ValueKind.COLORS_OF_MANA_SPENT" | "ValueKind.TOTAL_AMONG" | "ValueKind.COMMANDER_COLOUR_IDENTITY" | "ValueKind.DIE_ROLL_RESULT" | "ValueKind.AMOUNT_THIS_WAY" | "ValueKind.EVENT_AMOUNT_THIS_TURN" | "ValueKind.BLOCKERS_OF_SOURCE" | "ValueKind.PLAYER_COUNT";
export const ValueKindValues: Record<string, number> = { CONSTANT: 0, X: 1, COUNT: 2, POWER: 3, TOUGHNESS: 4, MANA_VALUE: 5, LIFE_TOTAL: 6, CARDS_IN_HAND: 7, POISON_COUNTERS: 8, ENERGY: 9, COUNTERS: 10, SUM: 11, PRODUCT: 12, DIFFERENCE: 13, HALF_ROUNDED_UP: 14, HALF_ROUNDED_DOWN: 15, MAXIMUM: 16, MINIMUM: 17, GREATEST_AMONG: 18, LEAST_AMONG: 19, UNCHANGED: 20, DEVOTION: 22, COLOURS_AMONG: 23, MANA_SPENT: 24, COST_PAID_POWER: 21, COST_PAID: 30, EVENT_AMOUNT: 25, EVENT_COUNT_THIS_TURN: 26, PARTY_SIZE: 60, COLORS_OF_MANA_SPENT: 61, TOTAL_AMONG: 27, COMMANDER_COLOUR_IDENTITY: 28, DIE_ROLL_RESULT: 29, AMOUNT_THIS_WAY: 7001, EVENT_AMOUNT_THIS_TURN: 7002, BLOCKERS_OF_SOURCE: 18001, PLAYER_COUNT: 18002 };

export type EnumZone = "Zone.LIBRARY" | "Zone.HAND" | "Zone.BATTLEFIELD" | "Zone.GRAVEYARD" | "Zone.STACK" | "Zone.EXILE" | "Zone.COMMAND";
export const ZoneValues: Record<string, number> = { LIBRARY: 0, HAND: 1, BATTLEFIELD: 2, GRAVEYARD: 3, STACK: 4, EXILE: 5, COMMAND: 6 };

export interface Ability {
  $: "Ability";
  kind: EnumAbilityKind;
  effects?: Array<Effect>;  // default []
  text?: IRString;  // default ""
  cost?: Cost;  // default {"$": "Cost"}
  timing?: EnumTiming;  // default "Timing.INSTANT"
  is_mana_ability?: boolean;  // default false
  is_loyalty_ability?: boolean;  // default false
  once_each_turn?: boolean;  // default false
  only_once?: boolean;  // default false
  reduced_by_own_mana_cost_on_entry?: boolean;  // default false
  activation_condition?: Condition;  // default {"$": "Condition"}
  trigger?: TriggerCondition | null;  // default null
  static_condition?: Condition;  // default {"$": "Condition"}
  functions_in?: { $set: Array<EnumZone> };  // default {"$set": ["Zone.BATTLEFIELD"]}
  keyword?: IRString;  // default ""
  link_id?: number;  // default 0
  quality?: ObjectFilter | PlayerFilter | Value | null;  // default null
  alternative_cost?: IRValue | null;  // default null
  additional_cost?: IRValue | null;  // default null
  chapter?: number;  // default 0
  is_characteristic_defining?: boolean;  // default false
  from_land_type?: boolean;  // default false
  unparsed?: boolean;  // default false
  remembered?: Array<number>;  // default []
}

export interface TriggerCondition {
  $: "TriggerCondition";
  event_kinds?: { $set: Array<EnumEventKind> };  // default {"$set": []}
  subject?: ObjectFilter | null;  // default null
  source?: ObjectFilter | null;  // default null
  players?: PlayerFilter | null;  // default null
  intervening_if?: Condition;  // default {"$": "Condition"}
  ordinal?: number;  // default 0
  alternatives?: Array<IRValue>;  // default []
  functions_in?: { $set: Array<EnumZone> };  // default {"$set": ["Zone.BATTLEFIELD"]}
  chapter?: number;  // default 0
  is_state_trigger?: boolean;  // default false
  room?: number;  // default 0
  counter_kind?: IRString;  // default ""
  each_counter?: boolean;  // default false
  batched?: boolean;  // default false
  once_each_turn?: boolean;  // default false
  phases?: { $set: Array<EnumPhase | number> };  // default {"$set": []}
  steps?: { $set: Array<EnumStep | number> };  // default {"$set": []}
  to_player?: boolean;  // default false
  from_zones?: { $set: Array<EnumZone> };  // default {"$set": []}
  expend?: number;  // default 0
  uses_last_known_information?: boolean;  // default false
  during_own_resolution?: boolean;  // default false
  text?: IRString;  // default ""
}

